"""Core data models shared across the metadata-aware RAG system."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass, field
from typing import Any, Dict, Optional


def _stable_id(*parts: str, length: int = 16) -> str:
    """Deterministic short id for documents/chunks."""
    payload = "\x1f".join(str(part) for part in parts)
    return hashlib.sha1(payload.encode("utf-8")).hexdigest()[:length]


@dataclass
class Document:
    """A source document plus its metadata.

    ``metadata`` is a free-form dictionary. This RAG system recognises the
    following conventional keys for filtering and ranking:

    * ``category``  -- categorical label (e.g. ``"technical"``, ``"legal"``)
    * ``author``    -- author name (filterable)
    * ``date``      -- ISO-8601 date, used for recency ranking
    * ``priority``  -- float in [0, 10], explicit importance score
    * ``tags``      -- list[str], used for query/tag relevance matching
    * ``source``    -- origin path/name, used for source-authority ranking
    * ``title``     -- display title

    Any other keys are preserved and usable in filters as well.
    """

    content: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None

    def __post_init__(self) -> None:
        if not self.doc_id:
            self.doc_id = _stable_id(self.content, str(self.metadata))

    @property
    def title(self) -> str:
        return str(self.metadata.get("title") or self.doc_id or "untitled")


@dataclass
class Chunk:
    """A chunked slice of a document carrying inherited metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None
    chunk_index: int = 0
    chunk_id: Optional[str] = None

    def __post_init__(self) -> None:
        if not self.chunk_id:
            self.chunk_id = _stable_id(self.doc_id or "", self.chunk_index, self.text)

    @property
    def source(self) -> str:
        return str(self.metadata.get("source", "unknown"))

"""Embedding providers.

The vector store accepts any object exposing ``embed(text)`` and
``embed_many(texts)``. Vectors may be:

* dense:  ``list[float]``     -- returned by SentenceTransformer / OpenAI
* sparse: ``dict[int, float]``-- returned by the built-in TF-IDF hasher

Every provider normalises its output so that cosine similarity reduces to a
plain dot product.
"""

from __future__ import annotations

import hashlib
import math
import os
import re
from collections import Counter
from typing import Any, Dict, List, Optional, Sequence, Union

Vector = Union[List[float], Dict[int, float]]


class HashingTfidfEmbedding:
    """Sparse TF-IDF embedder built on feature hashing (zero dependencies).

    This is a deterministic keyword-aware baseline: it captures exact term and
    bigram overlap and needs no downloads, which keeps demos and tests
    reproducible offline. It doubles as the "sparse" half of a hybrid setup.
    """

    _TOKEN_RE = re.compile(r"[a-z0-9]+")

    def __init__(
        self,
        n_features: int = 8192,
        ngram_range: tuple = (1, 2),
        sublinear_tf: bool = True,
    ) -> None:
        self.n_features = n_features
        self.ngram_range = ngram_range
        self.sublinear_tf = sublinear_tf
        self.document_frequency: Counter = Counter()
        self.n_documents: int = 0
        self.idf: Dict[int, float] = {}

    # -- tokenisation -------------------------------------------------
    def _tokens(self, text: str) -> List[str]:
        return self._TOKEN_RE.findall(text.lower())

    def _features(self, text: str) -> List[int]:
        tokens = self._tokens(text)
        lo, hi = self.ngram_range
        grams = list(tokens)
        for n in range(lo, hi + 1):
            if n == 1:
                continue
            for i in range(len(tokens) - n + 1):
                grams.append(" ".join(tokens[i : i + n]))
        return [self._hash(gram) for gram in grams]

    def _hash(self, token: str) -> int:
        digest = hashlib.blake2b(token.encode("utf-8"), digest_size=8).digest()
        return int.from_bytes(digest, "big") % self.n_features

    # -- corpus statistics -------------------------------------------
    def fit(self, texts: Sequence[str]) -> "HashingTfidfEmbedding":
        """Compute IDF statistics over the corpus (call before embedding)."""
        for text in texts:
            self.n_documents += 1
            for feature in set(self._features(text)):
                self.document_frequency[feature] += 1
        self.idf = {
            feature: math.log((1.0 + self.n_documents) / (1.0 + freq)) + 1.0
            for feature, freq in self.document_frequency.items()
        }
        return self

    def _idf_for(self, feature: int) -> float:
        if feature in self.idf:
            return self.idf[feature]
        return math.log((1.0 + self.n_documents) / 1.0) + 1.0

    # -- encoding -----------------------------------------------------
    def embed(self, text: str) -> Dict[int, float]:
        counts: Counter = Counter(self._features(text))
        total = sum(counts.values()) or 1.0
        vector: Dict[int, float] = {}
        for feature, count in counts.items():
            tf = count / total
            if self.sublinear_tf and tf > 0.0:
                tf = 1.0 + math.log(tf)
            vector[feature] = tf * self._idf_for(feature)
        norm = math.sqrt(sum(v * v for v in vector.values()))
        if norm > 0.0:
            vector = {key: value / norm for key, value in vector.items()}
        return vector

    def embed_many(self, texts: Sequence[str]) -> List[Dict[int, float]]:
        return [self.embed(text) for text in texts]

    # -- persistence --------------------------------------------------
    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.__class__.__name__,
            "n_features": self.n_features,
            "ngram_range": list(self.ngram_range),
            "sublinear_tf": self.sublinear_tf,
            "n_documents": self.n_documents,
            "idf": {str(key): value for key, value in self.idf.items()},
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "HashingTfidfEmbedding":
        obj = cls(
            n_features=int(data.get("n_features", 8192)),
            ngram_range=tuple(data.get("ngram_range", [1, 2])),
            sublinear_tf=bool(data.get("sublinear_tf", True)),
        )
        obj.n_documents = int(data.get("n_documents", 0))
        obj.idf = {int(key): float(value) for key, value in data.get("idf", {}).items()}
        obj.document_frequency = Counter(
            {int(key): float(value) for key, value in data.get("document_frequency", {}).items()}
        )
        return obj


class SentenceTransformerEmbedding:
    """Dense embeddings via sentence-transformers (optional dependency)."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError as exc:  # pragma: no cover - depends on environment
            raise ImportError(
                "sentence-transformers is required for dense embeddings. "
                "Install it with: pip install sentence-transformers"
            ) from exc
        self.model_name = model_name
        self.model = SentenceTransformer(model_name)

    def embed(self, text: str) -> List[float]:
        return self.embed_many([text])[0]

    def embed_many(self, texts: Sequence[str]) -> List[List[float]]:
        vectors = self.model.encode(list(texts), normalize_embeddings=True)
        return [vector.tolist() for vector in vectors]


class OpenAIEmbedding:
    """Dense embeddings via the OpenAI API (optional dependency + key)."""

    def __init__(
        self,
        model: str = "text-embedding-ada-002",
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
    ) -> None:
        try:
            import openai
        except ImportError as exc:  # pragma: no cover - depends on environment
            raise ImportError(
                "the openai package is required for OpenAI embeddings. "
                "Install it with: pip install openai"
            ) from exc
        self.model = model
        self.client = openai.OpenAI(
            api_key=api_key or os.environ.get("OPENAI_API_KEY"),
            base_url=base_url,
        )

    def embed(self, text: str) -> List[float]:
        return self.embed_many([text])[0]

    def embed_many(self, texts: Sequence[str]) -> List[List[float]]:
        response = self.client.embeddings.create(model=self.model, input=list(texts))
        return [item.embedding for item in response.data]


def build_embedding(name: str = "tfidf", **kwargs: Any) -> Any:
    """Factory for embedding backends.

    ``name`` is one of ``tfidf`` (default), ``sentence-transformers``,
    or ``openai``.
    """
    normalized = name.lower().replace("_", "-")
    if normalized in ("tfidf", "tf-idf", "sparse", "hashing"):
        return HashingTfidfEmbedding(**kwargs)
    if normalized in ("sentence", "sentence-transformers", "dense-mini"):
        return SentenceTransformerEmbedding(**kwargs)
    if normalized in ("openai", "ada", "text-embedding"):
        return OpenAIEmbedding(**kwargs)
    raise ValueError(f"Unknown embedding backend: {name!r}")

"""In-memory vector store with metadata filtering.

Filter semantics
----------------

A ``metadata_filter`` is a JSON-able dict evaluated against each chunk's
``metadata``. Supported forms:

* equality:       ``{"category": "technical"}``
* membership:     ``{"author": ["alice", "bob"]}``
* comparisons:    ``{"date": {"gte": "2024-01-01"}}``
* list contains:  ``{"tags": {"contains": "security"}}``
* presence:       ``{"priority": {"exists": true}}``
* boolean logic:  ``{"$and": [...], "$or": [...]}``

Comparison operators: ``eq, ne, gt, gte, lt, lte, in, nin, contains, exists``.
ISO-8601 date strings are compared as dates, so range filters over ``date``
work naturally.
"""

from __future__ import annotations

from datetime import date, datetime
from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

from .embeddings import Vector
from .models import Chunk

_OPS = frozenset({"eq", "ne", "gt", "gte", "lt", "lte", "in", "nin", "contains", "exists"})


# ---------------------------------------------------------------------------
# Metadata filter matching
# ---------------------------------------------------------------------------
def _parse_date(value: Any) -> Optional[date]:
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        try:
            return date.fromisoformat(value[:10])
        except ValueError:
            return None
    return None


def _compare(value: Any, target: Any) -> int:
    """Three-way comparison that treats ISO date strings as dates."""
    value_date, target_date = _parse_date(value), _parse_date(target)
    if value_date is not None and target_date is not None:
        return (value_date > target_date) - (value_date < target_date)
    try:
        return (value > target) - (value < target)
    except TypeError:
        return -1 if value is None else 1


def _matches_field(value: Any, condition: Any) -> bool:
    """Evaluate a single condition against one metadata value."""
    if isinstance(condition, dict) and any(op in _OPS for op in condition):
        for op, target in condition.items():
            if op not in _OPS:
                continue
            if op == "eq":
                if value != target:
                    return False
            elif op == "ne":
                if value == target:
                    return False
            elif op == "exists":
                if bool(target) != (value is not None):
                    return False
            elif value is None:
                return False
            elif op == "gt":
                if not _compare(value, target) > 0:
                    return False
            elif op == "gte":
                if not _compare(value, target) >= 0:
                    return False
            elif op == "lt":
                if not _compare(value, target) < 0:
                    return False
            elif op == "lte":
                if not _compare(value, target) <= 0:
                    return False
            elif op == "in":
                if value not in target:
                    return False
            elif op == "nin":
                if value in target:
                    return False
            elif op == "contains":
                if isinstance(value, (list, tuple, set)):
                    if target not in value:
                        return False
                elif isinstance(value, str):
                    if target not in value:
                        return False
                else:
                    return False
        return True
    if isinstance(condition, (list, tuple, set)):
        return value in condition
    return value == condition


def matches_metadata(
    metadata: Dict[str, Any],
    metadata_filter: Optional[Dict[str, Any]],
) -> bool:
    """Return True when ``metadata`` satisfies ``metadata_filter``."""
    if not metadata_filter:
        return True
    if "$and" in metadata_filter:
        return all(matches_metadata(metadata, sub) for sub in metadata_filter["$and"])
    if "$or" in metadata_filter:
        return any(matches_metadata(metadata, sub) for sub in metadata_filter["$or"])
    return all(_matches_field(metadata.get(key), cond) for key, cond in metadata_filter.items())


def filter_match_ratio(
    metadata: Dict[str, Any],
    metadata_filter: Optional[Dict[str, Any]],
) -> float:
    """Fraction of top-level filter keys the chunk *explicitly* satisfies.

    Every candidate already passed :func:`matches_metadata`; this finer ratio
    rewards chunks whose metadata explicitly declares the filtered fields
    (e.g. a document that declares ``category: technical`` rather than one
    that merely passes a negative filter by omission).
    """
    if not metadata_filter:
        return 1.0
    keys = [key for key in metadata_filter if not key.startswith("$")]
    if not keys:
        return 1.0
    matched = sum(
        1
        for key in keys
        if key in metadata and _matches_field(metadata.get(key), metadata_filter[key])
    )
    return matched / len(keys)


# ---------------------------------------------------------------------------
# Similarity
# ---------------------------------------------------------------------------
def cosine_similarity(a: Vector, b: Vector) -> float:
    """Cosine similarity for normalised sparse (dict) or dense (list) vectors."""
    if isinstance(a, dict) and isinstance(b, dict):
        small, large = (a, b) if len(a) <= len(b) else (b, a)
        return sum(small[key] * large[key] for key in small if key in large)
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return sum(x * y for x, y in zip(a, b))
    raise TypeError("vector representation mismatch (sparse vs dense)")


# ---------------------------------------------------------------------------
# Store
# ---------------------------------------------------------------------------
class VectorStore:
    """A lightweight in-memory vector index with metadata filtering."""

    def __init__(self, embedding: Any) -> None:
        self.embedding = embedding
        self.chunks: List[Chunk] = []
        self.vectors: List[Vector] = []

    def __len__(self) -> int:
        return len(self.chunks)

    def add_chunks(self, chunks: Sequence[Chunk]) -> None:
        new_chunks = list(chunks)
        vectors = self.embedding.embed_many([chunk.text for chunk in new_chunks])
        self.chunks.extend(new_chunks)
        self.vectors.extend(vectors)

    def search(
        self,
        query: str,
        k: int = 10,
        metadata_filter: Optional[Dict[str, Any]] = None,
    ) -> List[Tuple[Chunk, float]]:
        """Return the top-k chunks by cosine similarity after filtering."""
        query_vector = self.embedding.embed(query)
        scored: List[Tuple[float, int]] = []
        for idx, vector in enumerate(self.vectors):
            chunk = self.chunks[idx]
            if metadata_filter and not matches_metadata(chunk.metadata, metadata_filter):
                continue
            score = cosine_similarity(query_vector, vector)
            scored.append((score, idx))
        scored.sort(key=lambda item: item[0], reverse=True)
        return [(self.chunks[idx], score) for score, idx in scored[:k]]

    def candidate_count(self, metadata_filter: Optional[Dict[str, Any]] = None) -> int:
        if not metadata_filter:
            return len(self.chunks)
        return sum(1 for chunk in self.chunks if matches_metadata(chunk.metadata, metadata_filter))

"""Answer generation: prompt assembly plus an optional LLM backend."""

from __future__ import annotations

import os
import re
from typing import List, Optional

from .ranking import RankedResult

SYSTEM_PROMPT = """You are a precise assistant that answers questions using ONLY the provided context.

Rules:
1. Base every claim on the context. Do not use outside knowledge.
2. Cite the source of each claim with a bracketed number, e.g. [1] or [2].
3. If the context does not contain enough information, answer exactly:
   "I don't have enough information."

Context:
{context}

Question: {question}

Answer:"""


def format_context(results: List[RankedResult]) -> str:
    """Render ranked results as a numbered, metadata-annotated context block."""
    blocks = []
    for index, result in enumerate(results, start=1):
        meta = result.chunk.metadata
        header = ", ".join(
            f"{key}={meta.get(key)}"
            for key in ("source", "category", "date", "priority")
            if meta.get(key) is not None
        )
        blocks.append(f"[{index}] ({header})\n{result.chunk.text}")
    return "\n\n".join(blocks)


class LLMClient:
    """OpenAI-compatible chat client with an offline extractive fallback.

    When no API key is configured (or the call fails), the client returns a
    keyword-grounded extractive answer so the full pipeline stays runnable
    without any external service.
    """

    def __init__(
        self,
        model: str = "gpt-4o-mini",
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
        temperature: float = 0.2,
    ) -> None:
        self.model = model
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        self.base_url = base_url
        self.temperature = temperature

    def generate(self, question: str, results: List[RankedResult]) -> str:
        try:
            return self._generate_via_api(question, results)
        except Exception as exc:  # noqa: BLE001 - offline fallback is by design
            print(f"[generator] LLM unavailable ({exc}); using extractive fallback.")
            return self._generate_extractive(question, results)

    # -- API path -----------------------------------------------------
    def _generate_via_api(self, question: str, results: List[RankedResult]) -> str:
        import openai  # optional dependency, imported lazily

        client = openai.OpenAI(api_key=self.api_key, base_url=self.base_url)
        prompt = SYSTEM_PROMPT.format(
            context=format_context(results),
            question=question,
        )
        response = client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=self.temperature,
        )
        return response.choices[0].message.content or ""

    # -- offline fallback --------------------------------------------
    def _generate_extractive(self, question: str, results: List[RankedResult]) -> str:
        if not results:
            return "I don't have enough information."
        terms = {term for term in re.findall(r"[a-z0-9]+", question.lower()) if len(term) > 2}
        sentences: List[str] = []
        for index, result in enumerate(results, start=1):
            for sentence in re.split(r"(?<=[.!?])\s+", result.chunk.text):
                sentence = sentence.strip()
                if not sentence:
                    continue
                if terms and not any(term in sentence.lower() for term in terms):
                    continue
                sentences.append(f"[{index}] {sentence}")
        if not sentences:
            return "I don't have enough information."
        return "\n".join(sentences[:6])

"""Document loading, frontmatter parsing and chunking utilities."""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple, Union

from .models import Chunk, Document


# ---------------------------------------------------------------------------
# Frontmatter parsing (YAML-lite: scalars, booleans, numbers, lists)
# ---------------------------------------------------------------------------
def parse_frontmatter(text: str) -> Tuple[str, Dict[str, Any]]:
    """Split an optional ``--- key: value ---`` frontmatter block.

    Returns ``(body, metadata)``. Supports strings, integers, floats,
    booleans, and ``[a, b, c]`` lists.
    """
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return text, {}
    end: Optional[int] = None
    for index in range(1, len(lines)):
        if lines[index].strip() == "---":
            end = index
            break
    if end is None:
        return text, {}

    metadata: Dict[str, Any] = {}
    for line in lines[1:end]:
        if ":" not in line or line.lstrip().startswith("#"):
            continue
        key, _, raw = line.partition(":")
        key = key.strip()
        raw = raw.strip()
        if raw.startswith("[") and raw.endswith("]"):
            value = [
                item.strip().strip("\"'")
                for item in raw[1:-1].split(",")
                if item.strip()
            ]
        elif raw.lower() == "true":
            value = True
        elif raw.lower() == "false":
            value = False
        elif re.fullmatch(r"-?\d+", raw):
            value = int(raw)
        elif re.fullmatch(r"-?\d+\.\d+", raw):
            value = float(raw)
        else:
            value = raw.strip("\"'")
        metadata[key] = value

    body = "\n".join(lines[end + 1 :]).strip()
    return body, metadata


# ---------------------------------------------------------------------------
# Loading
# ---------------------------------------------------------------------------
def load_documents(files: Iterable[Union[str, os.PathLike]]) -> List[Document]:
    """Load markdown files, parsing frontmatter into document metadata."""
    documents: List[Document] = []
    for path in files:
        path = Path(path)
        text = path.read_text(encoding="utf-8")
        body, metadata = parse_frontmatter(text)
        metadata.setdefault("source", str(path))
        metadata.setdefault("title", path.stem)
        documents.append(Document(content=body, metadata=metadata))
    return documents


def documents_from_directory(directory: str, pattern: str = "*.md") -> List[Document]:
    """Load every file matching ``pattern`` inside ``directory``."""
    return load_documents(sorted(Path(directory).glob(pattern)))


# ---------------------------------------------------------------------------
# Chunking
# ---------------------------------------------------------------------------
def split_text(
    text: str,
    chunk_size: int = 800,
    chunk_overlap: int = 150,
    separators: Tuple[str, ...] = ("\n\n", "\n", ". ", " "),
) -> List[str]:
    """Recursive character splitting with overlap (pure Python).

    Sections are split greedily on the first separator that keeps pieces
    under ``chunk_size``; the final chunk list carries ``chunk_overlap``
    characters of context from the previous chunk.
    """
    if chunk_overlap >= chunk_size:
        raise ValueError("chunk_overlap must be smaller than chunk_size")

    chunks: List[str] = []

    def split_section(section: str, sep_index: int) -> None:
        if len(section) <= chunk_size:
            if section.strip():
                chunks.append(section.strip())
            return
        if sep_index >= len(separators):
            # No separator fits: hard-cut.
            chunks.append(section[:chunk_size].strip())
            rest = section[chunk_size:]
            if rest.strip():
                split_section(rest, sep_index)
            return

        parts = section.split(separators[sep_index])
        merged: List[str] = []
        buffer = ""
        for part in parts:
            candidate = buffer + separators[sep_index] + part if buffer else part
            if len(candidate) <= chunk_size:
                buffer = candidate
            else:
                if buffer:
                    merged.append(buffer)
                buffer = part
        if buffer:
            merged.append(buffer)
        for piece in merged:
            split_section(piece, sep_index + 1)

    split_section(text, 0)

    if chunk_overlap > 0 and len(chunks) > 1:
        overlapped: List[str] = []
        previous = ""
        for chunk in chunks:
            overlapped.append((previous[-chunk_overlap:] + chunk).strip() if previous else chunk)
            previous = chunk
        chunks = overlapped
    return [chunk for chunk in chunks if chunk]


def chunk_document(
    document: Document,
    chunk_size: int = 800,
    chunk_overlap: int = 150,
) -> List[Chunk]:
    """Split a document into chunks that inherit its metadata."""
    parts = split_text(document.content, chunk_size=chunk_size, chunk_overlap=chunk_overlap)
    return [
        Chunk(
            text=part,
            metadata=dict(document.metadata),
            doc_id=document.doc_id,
            chunk_index=index,
        )
        for index, part in enumerate(parts)
    ]
